<script lang="ts">
 import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import Status from '$lib/components/Status.svelte';import {workspace,projectProcess} from '$lib/stores/workspace';
 let query='',error='',notice='',busy='';
 $: rows=$workspace.projects.filter(p=>[p.name,p.framework,p.status,p.repo].join(' ').toLowerCase().includes(query.trim().toLowerCase()));
 function action(id:string,operation:'Start'|'Stop'|'Restart'){try{error='';busy=id;projectProcess(id,operation);notice=operation+' simulated. No container was changed.';}catch(e){error=e instanceof Error?e.message:'Action unavailable.';}finally{busy='';}}
</script>
<Heading title="Containers" subtitle="Application processes on this VPS. Current statuses are sample data."><a class="btn primary" href="/projects/new"><Icon name="Plus"/> New application</a></Heading>
<div class="stack"><div class="callout"><strong>Container controls are previews.</strong><p>Start, stop and restart update only the browser demonstration. Docker is not connected.</p></div>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}
<section class="card table-card"><div class="table-head"><div class="row between wrap"><h3>Application processes</h3><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search containers…" aria-label="Search containers"/></label></div></div><div class="table-wrap"><table><thead><tr><th>Application</th><th>Runtime</th><th>Status</th><th>Controls</th></tr></thead><tbody>{#each rows as p (p.id)}<tr><td><a class="link-btn" href={'/projects/'+p.id+'/overview'}>{p.name}</a><small style="display:block">{p.repo||p.source}</small></td><td>{p.framework}</td><td><Status value={p.status}/></td><td><div class="table-actions">{#if p.status==='Live'}<button class="btn secondary small" disabled={busy===p.id} on:click={()=>action(p.id,'Restart')}>Restart</button><button class="btn secondary small" disabled={busy===p.id} on:click={()=>action(p.id,'Stop')}>Stop</button>{:else if p.status==='Stopped'}<button class="btn secondary small" disabled={busy===p.id} on:click={()=>action(p.id,'Start')}>Start</button>{:else}<a class="btn secondary small" href={'/projects/'+p.id+'/deployments'}>Deployment needed</a>{/if}<a class="btn ghost small" href={'/projects/'+p.id+'/logs'}>Logs</a></div></td></tr>{:else}<tr><td colspan="4">No matching applications.</td></tr>{/each}</tbody></table></div></section>
</div>
